        problems += gl_untouched("L12", sandbox, path, gl_bytes(path), keep=(planted_name,))
        return problems, ["seam        : token_hex -> %s (planted), then %s" % (GL_PINNED_HEX, GL_FRESH_HEX),
                          "calls       : %d" % len(calls)]

