def gj_sink_missing(mod, cls_name):
    """One problem naming the reasoning methods *cls_name* lacks (red before Step 14, never a crash)."""
    cls = getattr(mod, cls_name, None)
    if cls is None:
        return ["the module defines no %s" % cls_name]
    absent = [m for m in GJ_SINK_METHODS if not callable(getattr(cls, m, None))]
    return ["%s defines no %s (Step 14 not landed)" % (cls_name, ", ".join(absent))] if absent else []


def gj_block_start(index, block):
    return ("content_block_start", {"type": "content_block_start", "index": index, "content_block": block})


def gj_block_delta(index, delta):
    return ("content_block_delta", {"type": "content_block_delta", "index": index, "delta": delta})


def gj_block_stop(index):
    return ("content_block_stop", {"type": "content_block_stop", "index": index})


def gj_finish_events(stop_reason="end_turn"):
    return [("message_delta", {"type": "message_delta", "delta": {"stop_reason": stop_reason, "stop_sequence": None},
                               "usage": dict(GJ_USAGE)}),
            ("message_stop", {"type": "message_stop"})]


def gj_fold(events):
    """The Anthropic message the encoder's *events* describe (J26): each block from its start
    plus its deltas (thinking_delta and signature_delta joined, input_json parsed), the
    message_start id and model, the message_delta stop_reason and usage."""
    message = {"id": None, "type": "message", "role": "assistant", "model": None, "content": [],
               "stop_reason": None, "stop_sequence": None, "usage": None}
    json_parts = {}
    for name, obj in events:
        if name == "message_start":
            inner = obj.get("message") or {}
            message["id"], message["model"] = inner.get("id"), inner.get("model")
        elif name == "content_block_start":
            block = dict(obj.get("content_block") or {})
            if block.get("type") == "tool_use":
                json_parts[len(message["content"])] = ""
            message["content"].append(block)
        elif name == "content_block_delta" and message["content"]:
            delta, block = obj.get("delta") or {}, message["content"][-1]
            kind = delta.get("type")
            if kind == "text_delta":
                block["text"] = block.get("text", "") + (delta.get("text") or "")
            elif kind == "thinking_delta":
                block["thinking"] = block.get("thinking", "") + (delta.get("thinking") or "")
            elif kind == "signature_delta":
                block["signature"] = block.get("signature", "") + (delta.get("signature") or "")
            elif kind == "input_json_delta":
                json_parts[len(message["content"]) - 1] += delta.get("partial_json") or ""
        elif name == "message_delta":
            message["stop_reason"] = (obj.get("delta") or {}).get("stop_reason")
            message["usage"] = obj.get("usage")
    for index, text in json_parts.items():
        try:
            message["content"][index]["input"] = json.loads(text)
        except ValueError:
            message["content"][index]["input"] = None
    return message


def gj_missing(mod, names):
    """One problem naming every symbol of *names* the module does not define (red, never a crash)."""
    absent = [n for n in names if not hasattr(mod, n)]
    if not absent:
        return []
    return ["the module defines no %s (Step 7 not landed)" % ", ".join(absent)]


def gj_events(data):
    """[(event, payload)] of encoder output: ASCII bytes made only of
    `event: <name>\\ndata: <json>\\n\\n` frames whose payload type is <name>.
    Raises ValueError (with the reason) on anything else."""
    if not isinstance(data, bytes):
        raise ValueError("returned %s, not bytes" % type(data).__name__)
    data.decode("ascii")        # UnicodeDecodeError is a ValueError
    if not data:
        return []
    if not data.endswith(b"\n\n"):
        raise ValueError("output does not end with a blank line: %r" % data[-40:])
    out = []
    for frame in data[:-2].split(b"\n\n"):
        lines = frame.split(b"\n")
        if (len(lines) != 2 or not lines[0].startswith(b"event: ")
                or not lines[1].startswith(b"data: ")):
            raise ValueError("frame %r is not one event line and one data line" % frame[:80])
        name = lines[0][len(b"event: "):].decode("ascii")
        payload = json.loads(lines[1][len(b"data: "):].decode("ascii"))
        if not isinstance(payload, dict) or payload.get("type") != name:
            raise ValueError("event %r carries a payload of type %r"
                             % (name, payload.get("type") if isinstance(payload, dict) else None))
        out.append((name, payload))
    return out


def gj_shape(events):
    """A compact (name, index) list of *events* for detail and FAIL lines."""
    return ["%s%s" % (name, "" if "index" not in payload else "[%s]" % payload["index"])
            for name, payload in events]


# Step 12 (part 1): the static AST rules J1-J4 and the census rule J13.  Each
# rule is a function of the source TEXT (J13: of the census ROWS), never of
# SERVER itself, so its planted negative control (J15-J19) runs the SAME
# function, unchanged, over a doctored input.  A rule returns [finding]; an
# empty list is a pass.
GJ_STATIC_CASES = (
    "front hardening markers kept",      # J1
    "no env, proxy, urllib, asyncio",    # J2
    "no Access-Control- literal",        # J3
    "upstream headers, pure units",      # J4
    "hand copies all declared",          # J13
    "control: 2nd compare_digest",       # J15 (J1)
    "control: HTTPS_PROXY read",         # J16 (J2)
    "control: CORS literal",             # J17 (J3)
    "control: three J4 plants",          # J18 (J4)
    "control: undeclared hand copy",     # J19 (J13)
    "control: J4a send plants",          # J23 (J4a)
    "control: J4a hook plants",          # J36 (J4a, R-0083)
    "kind registry: one table",          # J37 (R-0084)
    "control: kind registry plants",     # J38 (J37)
    "front policy bound",                # J40 (R-0072)
    "control: J40 plants",               # J41 (J40)
)

# J1 (Plan Step 8): the scopes allowed to call hmac.compare_digest, each with its
# exact count -- the bearer check and the OAuth state check.
GJ_DIGEST_SITES = {"_precheck": 1, "_oauth_state_matches": 1}
# J4a (Plan Step 8, KD-7): the scopes allowed to call _rt_send, each paired with the
# one header builder its headers argument must call.
GJ_SEND_SITES = {"_post": "_rt_upstream_headers", "_rt_oauth_post": "_rt_oauth_headers"}
# J4a amended (R-0083): _rt_send takes exactly these parameters; the last, the socket
# registration hook, is DATA (the shutdown registry) that _rt_send only hands to the
# connection constructor `cls(...)` -- never called, never given the connection -- so it
# cannot frame.  Amended again (R-0095): EVERY send site passes it, so every upstream
# socket -- a model call as well as a token POST -- is in the shutdown sweep from its
# connect on.
GJ_SEND_PARAMS = ("backend", "path", "headers", "body", "track")
GJ_SEND_HOOK = "track"
GJ_SEND_CONN_CTOR = "cls"

GJ_ENV_ATTRS = ("environ", "environb", "getenv", "getenvb")
GJ_PURE_FORBIDDEN = ("socket", "ssl", "http", "select", "time", "threading")   # NFR-8
GJ_PURE_UNITS = (2, 3, 4, 5, 6)          # J4c: the banners that must exist, once each, in order
GJ_BANNER_RE = re.compile(r"^# Unit (\d+):", re.M)


def gj_parse(source):
    """(tree, []) or (None, [finding]): a source that does not parse is itself a finding."""
    try:
        return ast.parse(source), []
    except (SyntaxError, ValueError) as exc:
        return None, ["the source does not parse: %s: %s" % (type(exc).__name__, exc)]


def gj_scopes(tree):
    """[(node, name of the innermost enclosing function or None)] for every node of *tree*."""
    out = []
    stack = [(tree, None)]
    while stack:
        node, scope = stack.pop()
        out.append((node, scope))
        inner = node.name if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) else scope
        stack.extend((child, inner) for child in ast.iter_child_nodes(node))
    return out


def gj_callee(call):
    """The bare name a Call invokes (`x.f(...)` and `f(...)` both give "f"), else None."""
    func = call.func
    if isinstance(func, ast.Attribute):
        return func.attr
    if isinstance(func, ast.Name):
        return func.id
    return None


def gj_is_name(node, name):
    return isinstance(node, ast.Name) and node.id == name


def gj_is_environ(node):
    return isinstance(node, ast.Attribute) and node.attr in ("environ", "environb") \
        and gj_is_name(node.value, "os")


def gj_scope_text(scope):
    return "%s()" % scope if scope else "module level"


def rule_j1(source):
    """J1: the copied front still holds its hardening markers -- _HeaderDeadlineReader
    defined and used, `headers.defects` read, and hmac.compare_digest called only in
    the GJ_DIGEST_SITES scopes, each exactly its count (the bearer check in _precheck,
    the OAuth state check in _oauth_state_matches)."""
    tree, found = gj_parse(source)
    if tree is None:
        return found
    defined = used = defects = False
    digests = []
    for node, scope in gj_scopes(tree):
        if isinstance(node, ast.ClassDef) and node.name == "_HeaderDeadlineReader":
            defined = True
        elif (isinstance(node, ast.Name) and node.id == "_HeaderDeadlineReader"
              and isinstance(node.ctx, ast.Load)):
            used = True
        elif isinstance(node, ast.Attribute) and node.attr == "defects" and (
                gj_is_name(node.value, "headers")
                or (isinstance(node.value, ast.Attribute) and node.value.attr == "headers")):
            defects = True
        elif isinstance(node, ast.Call) and gj_callee(node) == "compare_digest":
            digests.append((node.lineno, scope))
    if not defined:
        found.append("no class _HeaderDeadlineReader: the header deadline is gone")
    elif not used:
        found.append("_HeaderDeadlineReader is defined but never used")
    if not defects:
        found.append("headers.defects is never read: a malformed header block is no longer refused")
    digests.sort()
    sites = ", ".join(GJ_DIGEST_SITES)
    want = sum(GJ_DIGEST_SITES.values())
    if len(digests) != want:
        found.append("%d compare_digest call(s) (lines %s), expected exactly %d, in %s"
                     % (len(digests), [ln for ln, _s in digests], want, sites))
    for name, count in GJ_DIGEST_SITES.items():
        held = sum(1 for _ln, scope in digests if scope == name)
        if held != count:
            found.append("compare_digest called %d time(s) in %s(), expected %d" % (held, name, count))
    for lineno, scope in digests:
        if scope not in GJ_DIGEST_SITES:
            found.append("%d: compare_digest called in %s, not one of %s"
                         % (lineno, gj_scope_text(scope), sites))
    return found


def gj_env_key(node):
    """The key node an environment read *node* names (os.getenv(K), os.environ.get(K),
    os.environ[K], K in os.environ), else None."""
    if isinstance(node, ast.Call) and node.args:
        func = node.func
        if isinstance(func, ast.Attribute) and func.attr in ("getenv", "getenvb") \
                and gj_is_name(func.value, "os"):
            return node.args[0]
        if isinstance(func, ast.Attribute) and func.attr in ("get", "pop", "setdefault") \
                and gj_is_environ(func.value):
            return node.args[0]
    if isinstance(node, ast.Subscript) and gj_is_environ(node.value):
        key = node.slice
        return getattr(key, "value", key) if type(key).__name__ == "Index" else key
    if isinstance(node, ast.Compare) and len(node.ops) == 1 \
            and isinstance(node.ops[0], (ast.In, ast.NotIn)) and gj_is_environ(node.comparators[0]):
        return node.left
    return None


def rule_j2(source):
    """J2: no os.environ / os.getenv outside main(), none whose key ends in _PROXY
    (anywhere, main() included); no urllib.request; no asyncio; no
    socket.create_connection."""
    tree, found = gj_parse(source)
    if tree is None:
        return found
    for node, scope in gj_scopes(tree):
        line = getattr(node, "lineno", 0)
        if isinstance(node, ast.Attribute) and node.attr in GJ_ENV_ATTRS \
                and gj_is_name(node.value, "os") and scope != "main":
            found.append("%d: os.%s read in %s, outside main()" % (line, node.attr, gj_scope_text(scope)))
        key = gj_env_key(node)
        if isinstance(key, ast.Constant) and isinstance(key.value, (str, bytes)):
            text = key.value.decode("ascii", "replace") if isinstance(key.value, bytes) else key.value
            if text.upper().endswith("_PROXY"):
                found.append("%d: an environment read of %s (a *_PROXY variable) in %s"
                             % (line, text, gj_scope_text(scope)))
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name == "urllib.request" or alias.name.startswith("urllib.request."):
                    found.append("%d: import %s" % (line, alias.name))
                if alias.name.split(".")[0] == "asyncio":
                    found.append("%d: import %s" % (line, alias.name))
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ""
            names = [alias.name for alias in node.names]
            if module == "urllib.request" or module.startswith("urllib.request.") \
                    or (module == "urllib" and "request" in names):
                found.append("%d: from %s import %s" % (line, module, ", ".join(names)))
            if module.split(".")[0] == "asyncio":
                found.append("%d: from %s import ..." % (line, module))
            if module == "os" and set(names) & set(GJ_ENV_ATTRS):
                found.append("%d: from os import %s (an environment read main() cannot scope)"
                             % (line, ", ".join(sorted(set(names) & set(GJ_ENV_ATTRS)))))
            if module == "socket" and "create_connection" in names:
                found.append("%d: from socket import create_connection" % line)
        elif isinstance(node, ast.Attribute):
            if node.attr == "request" and gj_is_name(node.value, "urllib"):
                found.append("%d: urllib.request referenced" % line)
            if node.attr == "create_connection" and gj_is_name(node.value, "socket"):
                found.append("%d: socket.create_connection referenced" % line)
        elif isinstance(node, ast.Name) and node.id == "asyncio":
            found.append("%d: asyncio referenced" % line)
    return sorted(set(found), key=lambda f: (int(f.split(":", 1)[0]), f))


def rule_j3(source):
    """J3: no string literal starting with Access-Control- (no CORS header, ever)."""
    tree, found = gj_parse(source)
    if tree is None:
        return found
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, (str, bytes)):
            text = node.value.decode("latin-1") if isinstance(node.value, bytes) else node.value
            if text.lower().startswith("access-control-"):
                found.append("%d: a literal %r" % (node.lineno, text[:60]))
    return sorted(found, key=lambda f: (int(f.split(":", 1)[0]), f))


def gj_banners(source):
    """({unit: [line, ...]}) of every `# Unit N:` banner line in *source*."""
    lines = {}
    for match in GJ_BANNER_RE.finditer(source):
        lines.setdefault(int(match.group(1)), []).append(source.count("\n", 0, match.start()) + 1)
    return lines


def rule_j4(source):
    """J4: (a) every putheader call is inside _rt_send, and _rt_send is called only
    in the GJ_SEND_SITES scopes, exactly once each, with that scope's paired builder
    call as its headers argument (_post -> _rt_upstream_headers(...), _rt_oauth_post
    -> _rt_oauth_headers(...)); amended for R-0083, _rt_send's parameters are exactly
    GJ_SEND_PARAMS and its registration hook `track` is used in it only as an argument of
    the connection constructor cls(...), so the hook is a registry, never a second framing
    owner; amended for R-0095, every send site passes that hook; (b) the attribute client_headers is read only inside
    _rt_upstream_headers; (c) nothing between the `# Unit 2:` and `# Unit 6:`
    banners references socket, ssl, http, select, time or threading -- and a
    missing, repeated or out-of-order banner is itself a finding."""
    tree, found = gj_parse(source)
    if tree is None:
        return found
    scoped = gj_scopes(tree)

    # (a)
    putheaders, sends = [], []
    for node, scope in scoped:
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) \
                and node.func.attr == "putheader":
            putheaders.append((node.lineno, scope))
        elif isinstance(node, ast.Call) and gj_callee(node) == "_rt_send":
            sends.append((node, scope))
    if not putheaders:
        found.append("(a) no putheader call at all: the rule would pass vacuously")
    for lineno, scope in sorted(putheaders, key=lambda p: p[0]):
        if scope != "_rt_send":
            found.append("%d: putheader called in %s, not _rt_send" % (lineno, gj_scope_text(scope)))
    sites = ", ".join(GJ_SEND_SITES)
    if len(sends) != len(GJ_SEND_SITES):
        found.append("(a) _rt_send is called at %d site(s) (lines %s), expected exactly %d, one each in %s"
                     % (len(sends), sorted(n.lineno for n, _s in sends), len(GJ_SEND_SITES), sites))
    for name in GJ_SEND_SITES:
        held = sum(1 for _n, scope in sends if scope == name)
        if held != 1:
            found.append("(a) _rt_send is called %d time(s) in %s(), expected exactly one" % (held, name))
    for node, scope in sorted(sends, key=lambda s: s[0].lineno):
        if scope not in GJ_SEND_SITES:
            found.append("%d: _rt_send called in %s, not one of %s" % (node.lineno, gj_scope_text(scope), sites))
            continue
        builder = GJ_SEND_SITES[scope]
        headers = node.args[2] if len(node.args) > 2 else next(
            (kw.value for kw in node.keywords if kw.arg == "headers"), None)
        if not (isinstance(headers, ast.Call) and gj_callee(headers) == builder):
            found.append("%d: _rt_send's headers argument in %s() is not %s(...)"
                         % (node.lineno, scope, builder))
        hooked = len(node.args) > len(GJ_SEND_PARAMS) - 1 or any(
            kw.arg in (GJ_SEND_HOOK, None) for kw in node.keywords)
        if not hooked:
            found.append("%d: _rt_send in %s() does not pass the registration hook; every send "
                         "joins the shutdown registry (R-0095)" % (node.lineno, scope))
    # (a, R-0083) the registration hook is data handed to the connection constructor only.
    defs = [n for n, _s in scoped if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name == "_rt_send"]
    if len(defs) != 1:
        found.append("(a) _rt_send is defined %d time(s), expected exactly once" % len(defs))
    for fdef in defs:
        args = fdef.args
        names = tuple(a.arg for a in args.posonlyargs + args.args + args.kwonlyargs)
        if names != GJ_SEND_PARAMS or args.vararg is not None or args.kwarg is not None:
            found.append("%d: _rt_send's parameters are %s, expected exactly %s"
                         % (fdef.lineno, list(names) + (["*" + args.vararg.arg] if args.vararg else [])
                            + (["**" + args.kwarg.arg] if args.kwarg else []), list(GJ_SEND_PARAMS)))
        handed = set()
        for call in ast.walk(fdef):
            if isinstance(call, ast.Call) and gj_is_name(call.func, GJ_SEND_CONN_CTOR):
                handed.update(id(a) for a in call.args)
                handed.update(id(kw.value) for kw in call.keywords)
        for use in ast.walk(fdef):
            if isinstance(use, ast.Name) and use.id == GJ_SEND_HOOK and id(use) not in handed:
                found.append("%d: the hook `%s` is used in _rt_send() other than as an argument of the "
                             "connection constructor %s(...)" % (use.lineno, GJ_SEND_HOOK, GJ_SEND_CONN_CTOR))

    # (b)
    reads_inside = 0
    for node, scope in scoped:
        read = None
        if isinstance(node, ast.Attribute) and node.attr == "client_headers" \
                and isinstance(node.ctx, ast.Load):
            read = "client_headers read"
        elif isinstance(node, ast.Call) and gj_is_name(node.func, "getattr") and len(node.args) > 1 \
                and isinstance(node.args[1], ast.Constant) and node.args[1].value == "client_headers":
            read = "client_headers read (getattr)"
        if read is None:
            continue
        if scope == "_rt_upstream_headers":
            reads_inside += 1
        else:
            found.append("%d: %s in %s, not _rt_upstream_headers"
                         % (node.lineno, read, gj_scope_text(scope)))
    if not reads_inside:
        found.append("(b) _rt_upstream_headers reads no client_headers: the rule would pass vacuously")

    # (c)
    banners = gj_banners(source)
    order = []
    for unit in GJ_PURE_UNITS:
        at = banners.get(unit, [])
        if not at:
            found.append("(c) the `# Unit %d:` banner is missing" % unit)
        elif len(at) > 1:
            found.append("(c) the `# Unit %d:` banner appears %d times (lines %s)" % (unit, len(at), at))
        else:
            order.append(at[0])
    if len(order) == len(GJ_PURE_UNITS) and order != sorted(order):
        found.append("(c) the unit 2-6 banners are out of order (lines %s)" % order)
    elif len(order) == len(GJ_PURE_UNITS):
        first, last = order[0], order[-1]

        def unit_of(lineno):
            return max(u for u, ln in zip(GJ_PURE_UNITS, order) if ln <= lineno)

        hits = set()
        for node in ast.walk(tree):
            lineno = getattr(node, "lineno", None)
            if lineno is None or not first < lineno < last:
                continue
            names = []
            if isinstance(node, ast.Name):
                names.append(node.id)
            elif isinstance(node, ast.Import):
                names += [alias.name.split(".")[0] for alias in node.names]
                names += [alias.asname for alias in node.names if alias.asname]
            elif isinstance(node, ast.ImportFrom):
                names.append((node.module or "").split(".")[0])
                names += [alias.asname or alias.name for alias in node.names]
            for name in names:
                if name in GJ_PURE_FORBIDDEN:
                    hits.add((lineno, "%d: unit %d references %r (units 2-5 take no socket and "
                                      "no clock)" % (lineno, unit_of(lineno), name)))
        found += [text for _ln, text in sorted(hits)]
    return found


def rule_j13(rows, reasons):
    """J13: every (host, name) census row for llm-router.py has a HAND_COPY_REASONS entry."""
    found = []
    for host, name in rows:
        base = os.path.basename(host)
        if base == "llm-router.py" and (base, name) not in reasons:
            found.append("%s: %s is a hand copy with no HAND_COPY_REASONS entry" % (host, name))
    return found


# J40 (R-0072): the HTTP front's members are shared with mcp-proxy, so the policy
# they read reaches them injected -- the logger as the server's class-level
# front_log, the per-recv timeout as the handler's own `timeout`, the reader's cap
# as a constructor argument -- never as a host global read inside a member (PD-1..PD-7).
GJ_FRONT_SERVER = "_RouterHttpServer"
GJ_FRONT_HANDLER = "_RouterHandler"
GJ_FRONT_CAP = "_HTTP_SOCKET_TIMEOUT_S"
GJ_FRONT_TIMEOUT = "_HTTP_HEADER_TIMEOUT_S"
GJ_FRONT_TOKEN_MIN = "_TOKEN_MIN_LEN"     # (f): _http_token_value's 3rd argument
GJ_FRONT_ERROR = "ConfigError"            # (f): and its 4th
# (class, the members that must not read it, the host global)
GJ_FRONT_GLOBAL_READS = ((GJ_FRONT_SERVER, ("server_bind", "process_request", "handle_error"), "log"),
                         (GJ_FRONT_HANDLER, ("parse_request",), GJ_FRONT_TIMEOUT))
GJ_FRONT_POLICY_PREFIXES = ("_HTTP_", "_TOKEN_")


def gj_class_assign(cls, target, value):
    """True when the body of ClassDef *cls* holds `target = value` (both bare names)."""
    return any(isinstance(stmt, ast.Assign) and len(stmt.targets) == 1
               and gj_is_name(stmt.targets[0], target) and gj_is_name(stmt.value, value)
               for stmt in cls.body)


def rule_j40(source):
    """J40 (R-0072): the front's policy is injected, never read as a host global.
    (a) _RouterHttpServer holds `front_log = log`; (b) _RouterHandler holds
    `timeout = _HTTP_HEADER_TIMEOUT_S`; (c) every _HeaderDeadlineReader call passes
    exactly two positional args, the cap _HTTP_SOCKET_TIMEOUT_S; (d) server_bind,
    process_request and handle_error read no `log`, parse_request no
    _HTTP_HEADER_TIMEOUT_S; (e) PD-7: no other class attribute of either class
    snapshots an _HTTP_* / _TOKEN_* constant at class definition; (f) every
    _http_token_value call passes exactly four positional args, the 3rd
    _TOKEN_MIN_LEN and the 4th ConfigError."""
    tree, found = gj_parse(source)
    if tree is None:
        return found
    classes = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name in (GJ_FRONT_SERVER, GJ_FRONT_HANDLER):
            classes.setdefault(node.name, node)
    for name in (GJ_FRONT_SERVER, GJ_FRONT_HANDLER):
        if name not in classes:
            found.append("no class %s" % name)
    server = classes.get(GJ_FRONT_SERVER)
    handler = classes.get(GJ_FRONT_HANDLER)
    # (a), (b) -- the two class-level seams.
    if server is not None and not gj_class_assign(server, "front_log", "log"):
        found.append("%s: no class-level front_log = log" % GJ_FRONT_SERVER)
    if handler is not None and not gj_class_assign(handler, "timeout", GJ_FRONT_TIMEOUT):
        found.append("%s: no class-level timeout = %s" % (GJ_FRONT_HANDLER, GJ_FRONT_TIMEOUT))
    # (c) -- the reader's cap is a constructor argument, this host's socket timeout.
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and gj_is_name(node.func, "_HeaderDeadlineReader"):
            if len(node.args) != 2 or node.keywords:
                what = "%d args" % (len(node.args) + len(node.keywords))
            elif not gj_is_name(node.args[1], GJ_FRONT_CAP):
                what = ast.dump(node.args[1])
            else:
                continue
            found.append("%d: _HeaderDeadlineReader cap is %s, expected %s" % (node.lineno, what, GJ_FRONT_CAP))
    # (d) -- no host global read inside a shared member.
    for cls_name, members, glob in GJ_FRONT_GLOBAL_READS:
        cls = classes.get(cls_name)
        if cls is None:
            continue
        for stmt in cls.body:
            if not (isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name in members):
                continue
            for node in ast.walk(stmt):
                if isinstance(node, ast.Name) and node.id == glob and isinstance(node.ctx, ast.Load):
                    found.append("%d: %s.%s reads the host global %s" % (node.lineno, cls_name, stmt.name, glob))
    # (f) -- the token floor and the refusal's error class are the host's, passed in.
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and gj_is_name(node.func, "_http_token_value"):
            if len(node.args) != 4 or node.keywords:
                what = "%d args" % (len(node.args) + len(node.keywords))
            elif gj_is_name(node.args[2], GJ_FRONT_TOKEN_MIN) and gj_is_name(node.args[3], GJ_FRONT_ERROR):
                continue
            else:
                what = "%s, %s" % (ast.dump(node.args[2]), ast.dump(node.args[3]))
            found.append("%d: _http_token_value called with %s, expected %s, %s"
                         % (node.lineno, what, GJ_FRONT_TOKEN_MIN, GJ_FRONT_ERROR))
    # (e) -- PD-7: a class attribute is bound once, at class definition, so a rig
    # patch of the module constant never reaches it; `timeout` alone is patched in step.
    for cls in (server, handler):
        if cls is None:
            continue
        for stmt in cls.body:
            if isinstance(stmt, ast.Assign):
                targets, value = stmt.targets, stmt.value
            elif isinstance(stmt, ast.AnnAssign) and stmt.value is not None:
                targets, value = [stmt.target], stmt.value
            else:
                continue
            reads = sorted({node.id for node in ast.walk(value)
                            if isinstance(node, ast.Name) and node.id.startswith(GJ_FRONT_POLICY_PREFIXES)})
            if not reads:
                continue
            if cls is handler and len(targets) == 1 and gj_is_name(targets[0], "timeout") \
                    and gj_is_name(value, GJ_FRONT_TIMEOUT):
                continue
            shown = ", ".join(ast.unparse(target) for target in targets)
            found.append("%d: class attribute %s snapshots %s at class definition (PD-7)"
                         % (stmt.lineno, shown, ", ".join(reads)))
    return found


