def gj_control(checker, clean, planted, needles):
    """(problems, detail) of one planted control: *checker* over *clean* must report
    nothing; over *planted* it must report every needle.  The checker is a parameter
    so the SC-3 red run can hand it a stub that returns no finding."""
    problems = []
    if planted == clean:
        problems.append("the plant did not change the input (an anchor drifted)")
    base = checker(clean)
    if base:
        problems.append("the clean baseline already has %d finding(s): %s" % (len(base), base[:3]))
    got = checker(planted)
    for needle in needles:
        if not any(needle in finding for finding in got):
            problems.append("the plant %r was not reported (findings: %s)" % (needle, got[:4] or "none"))
    return problems, ["clean       : %d finding(s)" % len(base)] + \
        ["planted     : %s" % finding for finding in (got or ["no finding"])]


def group_j_static(suite):
    """J1-J4, J13, J37 and J40 over the live router, then their planted controls J15-J19, J23, J36,
    J38 and J41."""
    rel = os.path.relpath(SERVER, H.REPO_ROOT)
    results = {}
    try:
        with open(SERVER, "r", encoding="utf-8") as fh:
            source = fh.read()
    except OSError as exc:
        source = None
        why = "cannot read %s: %s: %s" % (rel, type(exc).__name__, exc)
        for cid in GJ_STATIC_CASES[:4]:
            results[cid] = ([why], [])

    if source is not None:
        tree, _bad = gj_parse(source)
        digests = sorted(node.lineno for node in ast.walk(tree)
                         if isinstance(node, ast.Call) and gj_callee(node) == "compare_digest") \
            if tree is not None else []
        sends = sorted(node.lineno for node in ast.walk(tree)
                       if isinstance(node, ast.Call) and gj_callee(node) == "_rt_send") \
            if tree is not None else []
        banners = gj_banners(source)
        live = (
            (rule_j1, ["scope       : every node of %s" % rel,
                       "digests     : compare_digest at line(s) %s" % digests]),
            (rule_j2, ["scope       : every node of %s; os.environ/os.getenv allowed in main() "
                       "only, never a *_PROXY key" % rel]),
            (rule_j3, ["scope       : every str/bytes constant of %s" % rel]),
            (rule_j4, ["_rt_send    : called at line(s) %s" % sends,
                       "banners     : %s" % ", ".join("unit %d @ %s" % (u, banners.get(u))
                                                     for u in GJ_PURE_UNITS),
                       "forbidden   : %s between unit 2 and unit 6" % ", ".join(GJ_PURE_FORBIDDEN)]),
        )
        for cid, (rule, detail) in zip(GJ_STATIC_CASES, live):
            try:
                results[cid] = (rule(source), detail)
            except Exception as exc:  # noqa: BLE001 -- a broken rule fails, never aborts the group
                results[cid] = (["rule raised %s: %s" % (type(exc).__name__, str(exc)[:200])], detail)

    # J13 -- the generator's own census, judged FAIL-grade for this host.
    cid = GJ_STATIC_CASES[4]
    try:
        amg = H.load_module_from_path("ph_amalgamate_j", H.repo_path("Scripts", "amalgamate.py"))
        rows = amg.hand_copies(amg.load_all_blocks(), [pathlib.Path(SERVER)])
        results[cid] = (rule_j13(rows, amg.HAND_COPY_REASONS),
                        ["census      : %s" % ("%s: %s" % row) for row in rows]
                        or ["census      : no hand copy in %s" % rel])
    except (Exception, SystemExit) as exc:  # noqa: BLE001 -- a broken census fails the case
        results[cid] = (["the census raised %s: %s" % (type(exc).__name__, str(exc)[:200])], [])

    # J37 -- the one kind registry, over the live router.
    if source is not None:
        cid = "kind registry: one table"
        try:
            results[cid] = (rule_j37(source),
                            ["scope       : %s, derived once from %s: %s" % (rel, GJ_REG_TABLE,
                                                                          ", ".join(GJ_REG_DERIVED)),
                             "check       : %s(%s) at module level" % (GJ_REG_CHECK, GJ_REG_TABLE)])
        except Exception as exc:  # noqa: BLE001 -- a broken rule fails, never aborts the group
            results[cid] = (["rule raised %s: %s" % (type(exc).__name__, str(exc)[:200])], [])

    # J40 -- the front's injected policy, over the live router (R-0072).
    if source is not None:
        cid = "front policy bound"
        try:
            results[cid] = (rule_j40(source),
                            ["scope       : %s: %s, %s, every _HeaderDeadlineReader call"
                             % (rel, GJ_FRONT_SERVER, GJ_FRONT_HANDLER),
                             "cap         : %s; per-recv timeout: self.timeout; logger: self.front_log"
                             % GJ_FRONT_CAP])
        except Exception as exc:  # noqa: BLE001 -- a broken rule fails, never aborts the group
            results[cid] = (["rule raised %s: %s" % (type(exc).__name__, str(exc)[:200])], [])

    for cid, (checker, clean, planted, needles) in GJ_CONTROLS.items():
        try:
            results[cid] = gj_control(checker, clean, planted, needles)
        except Exception as exc:  # noqa: BLE001
            results[cid] = (["control raised %s: %s" % (type(exc).__name__, str(exc)[:200])], [])

    for cid in GJ_STATIC_CASES:
        problems, detail = results.get(cid, (["case did not run"], []))
        suite.record(GJ, cid, problems, detail=detail)


def group_j(suite, fixture_root, pyc_before, tree_before):
    """J. static and hygiene -- Step 7's in-process cases: the sans-IO
    AnthropicSseEncoder's invariants and _rt_check_forward_tables.

    A missing symbol FAILS the case with its name (the red state before Step 7),
    never crashes the group.  *fixture_root*, *pyc_before* and *tree_before*
    are for Step 12's J14, J22 and J9/J10 (group_j_hygiene, run last).
    """
    group_j_static(suite)
    results = {}
    try:
        mod = H.load_module_from_path("ph_llm_router_j", SERVER)
    except Exception as exc:  # noqa: BLE001 -- an import failure fails the group
        for cid in GJ_CASES:
            suite.record(GJ, cid, ["cannot import %s: %s: %s"
                                   % (os.path.relpath(SERVER, H.REPO_ROOT),
                                      type(exc).__name__, exc)])
        group_j_hygiene(suite, fixture_root, pyc_before, tree_before)
        return

    def encoder():
        return mod.AnthropicSseEncoder(GJ_MESSAGE_ID, GJ_MODEL)

    def j6():
        problems = gj_missing(mod, ("AnthropicSseEncoder",))
        if problems:
            return problems, []
        enc = encoder()
        enc.start(3)
        enc.text("tf j6")
        err = enc.error("api_error", "tf j6 failure")
        try:
            events = gj_events(err)
        except ValueError as exc:
            events = []
            problems.append("error() output is malformed: %s" % exc)
        want = [("error", {"type": "error", "error": {"type": "api_error", "message": "tf j6 failure"}})]
        if events != want:
            problems.append("error() emitted %s, expected exactly one event: error envelope"
                            % gj_shape(events))
        if getattr(enc, "closed", None) is not True:
            problems.append("closed is %r after error(), expected True" % (getattr(enc, "closed", None),))
        after = (("start", lambda: enc.start(1)), ("text", lambda: enc.text("tf after")),
                 ("tool_block", lambda: enc.tool_block(*GJ_TOOL)), ("ping", enc.ping),
                 ("finish", lambda: enc.finish("end_turn", dict(GJ_USAGE))),
                 ("error", lambda: enc.error("api_error", "tf again")))
        shown = []
        for name, call in after:
            got = call()
            shown.append("%s=%r" % (name, got[:24] if isinstance(got, bytes) else got))
            if got != b"" or not isinstance(got, bytes):
                problems.append("%s() after error() returned %r, expected b\"\""
                                % (name, got[:60] if isinstance(got, bytes) else got))
        if getattr(enc, "closed", None) is not True:
            problems.append("closed flipped back to %r" % (getattr(enc, "closed", None),))
        return problems, ["error()     : %s" % gj_shape(events),
                          "after       : %s" % ", ".join(shown)]

    def j7():
        problems = gj_missing(mod, ("AnthropicSseEncoder",))
        if problems:
            return problems, []
        enc = encoder()
        enc.start(3)
        tool = enc.tool_block(*GJ_TOOL)
        fin = enc.finish("end_turn", dict(GJ_USAGE))
        try:
            tool_events, fin_events = gj_events(tool), gj_events(fin)
        except ValueError as exc:
            return ["malformed encoder output: %s" % exc], []
        deltas = [p for n, p in fin_events if n == "message_delta"]
        if len(deltas) != 1:
            problems.append("finish() emitted %d message_delta event(s), expected 1" % len(deltas))
        else:
            reason = (deltas[0].get("delta") or {}).get("stop_reason")
            if reason != "tool_use":
                problems.append("stop_reason %r after a tool_block with finish(\"end_turn\"), "
                                "expected \"tool_use\"" % (reason,))
            if deltas[0].get("usage") != GJ_USAGE:
                problems.append("message_delta usage %r, expected %r" % (deltas[0].get("usage"), GJ_USAGE))
        if not fin_events or fin_events[-1][0] != "message_stop":
            problems.append("finish() does not end with message_stop: %s" % gj_shape(fin_events))
        starts = [p for n, p in tool_events if n == "content_block_start"]
        block = starts[0].get("content_block") if starts else None
        if block != {"type": "tool_use", "id": GJ_TOOL[0], "name": GJ_TOOL[1], "input": {}}:
            problems.append("tool_block's content_block_start carries %r" % (block,))
        partial = [((p.get("delta") or {}).get("type"), (p.get("delta") or {}).get("partial_json"))
                   for n, p in tool_events if n == "content_block_delta"]
        if partial != [("input_json_delta", GJ_TOOL[2])]:
            problems.append("tool_block's deltas %r, expected one input_json_delta with the arguments"
                            % (partial,))
        return problems, ["tool_block  : %s" % gj_shape(tool_events),
                          "finish      : %s, stop_reason %r"
                          % (gj_shape(fin_events),
                             (deltas[0].get("delta") or {}).get("stop_reason") if deltas else None)]

    def j8():
        problems = gj_missing(mod, ("AnthropicSseEncoder",))
        if problems:
            return problems, []
        enc = encoder()
        try:
            start = gj_events(enc.start(3))
            text = gj_events(enc.text("tf j8"))
            tool = gj_events(enc.tool_block(*GJ_TOOL))
            fin = gj_events(enc.finish("tool_use", dict(GJ_USAGE)))
        except ValueError as exc:
            return ["malformed encoder output: %s" % exc], []
        if [n for n, _p in start] != ["message_start"]:
            problems.append("start() emitted %s, expected one message_start" % gj_shape(start))
        got = gj_shape(text + tool + fin)
        want = ["content_block_start[0]", "content_block_delta[0]", "content_block_stop[0]",
                "content_block_start[1]", "content_block_delta[1]", "content_block_stop[1]",
                "message_delta", "message_stop"]
        if got != want:
            problems.append("events after message_start %s, expected %s" % (got, want))
        if "content_block_stop[0]" not in gj_shape(tool):
            problems.append("tool_block() did not close the open text block itself (stop[0] not in "
                            "its own output: %s)" % gj_shape(tool))
        for name, payload in text:
            if name == "content_block_start" and payload.get("content_block") != {"type": "text", "text": ""}:
                problems.append("the text block starts as %r" % (payload.get("content_block"),))
            if name == "content_block_delta" and payload.get("delta") != {"type": "text_delta",
                                                                           "text": "tf j8"}:
                problems.append("the text delta is %r" % (payload.get("delta"),))
        for name, payload in tool:
            if name == "content_block_start" and (payload.get("content_block") or {}).get("type") != "tool_use":
                problems.append("block 1 starts as %r, expected tool_use" % (payload.get("content_block"),))
        return problems, ["text        : %s" % gj_shape(text),
                          "tool_block  : %s" % gj_shape(tool),
                          "finish      : %s" % gj_shape(fin)]

    def j12():
        problems = gj_missing(mod, ("_rt_check_forward_tables", "KIND_CLASSES", "_NEVER_FORWARD"))
        if problems:
            return problems, []
        table = mod.KIND_CLASSES
        kinds = tuple(sorted(table))
        if kinds != GJ_KINDS:
            problems.append("KIND_CLASSES holds %s, expected all of %s (a partial table makes the "
                            "check vacuous)" % (list(kinds), list(GJ_KINDS)))
        if "authorization" not in mod._NEVER_FORWARD:
            problems.append("_NEVER_FORWARD does not hold \"authorization\"")
        try:
            mod._rt_check_forward_tables(table)
        except Exception as exc:  # noqa: BLE001 -- a refusal of the real table is the finding
            problems.append("the real KIND_CLASSES was refused: %s: %s" % (type(exc).__name__, exc))
        shown = []
        for kind in kinds:
            cls = table[kind]
            before = frozenset(cls.FORWARDABLE)
            doctored = dict(table)
            doctored[kind] = type("TfDoctored" + cls.__name__, (cls,),
                                  {"FORWARDABLE": before | {"authorization"}})
            try:
                mod._rt_check_forward_tables(doctored)
            except Exception as exc:  # noqa: BLE001 -- any refusal is the expected answer
                shown.append("%s=%s" % (kind, type(exc).__name__))
            else:
                shown.append("%s=accepted" % kind)
                problems.append("%s: a FORWARDABLE with \"authorization\" was accepted" % kind)
            if frozenset(table[kind].FORWARDABLE) != before:
                problems.append("%s: the real class's FORWARDABLE changed under the doctored copy" % kind)
        return problems, ["real table  : %s accepted" % ", ".join(kinds),
                          "doctored    : + authorization -> %s" % ", ".join(shown)]

    def j21():
        problems = []
        dumped = None
        if hasattr(mod, "_rt_dumps"):
            try:
                dumped = mod._rt_dumps({"x": "\udfff"})
            except Exception as exc:  # noqa: BLE001 -- raising is the defect
                problems.append("_rt_dumps raised %s on a lone surrogate" % type(exc).__name__)
            else:
                if dumped != b'{"x":"\\udfff"}':
                    problems.append("_rt_dumps({\"x\": \"\\udfff\"}) -> %r, expected b'{\"x\":\"\\\\udfff\"}'"
                                    % (dumped,))
        else:
            problems += gj_missing(mod, ("_rt_dumps",))
        text = None
        missing = gj_missing(mod, ("AnthropicSseEncoder",))
        if missing:
            problems += missing
        else:
            enc = encoder()
            enc.start(1)
            try:
                text = enc.text("a\ud800b")
            except Exception as exc:  # noqa: BLE001 -- raising is the defect
                problems.append("text(\"a\\ud800b\") raised %s" % type(exc).__name__)
            else:
                try:
                    events = gj_events(text)
                except ValueError as exc:
                    events = []
                    problems.append("text() output is not ASCII SSE: %s" % exc)
                if b"\\ud800" not in (text if isinstance(text, bytes) else b""):
                    problems.append("text() output carries no \\ud800 escape: %r" % (text,))
                deltas = [p.get("delta") for n, p in events if n == "content_block_delta"]
                if deltas != [{"type": "text_delta", "text": "a\ud800b"}]:
                    problems.append("the delta round-trips as %r" % (deltas,))
        return problems, ["_rt_dumps   : %r" % (dumped,),
                          "text()      : %r" % ((text or b"")[-80:],)]

    think_start = {"type": "thinking", "thinking": "", "signature": ""}
    text_start = {"type": "text", "text": ""}
    tool_start = {"type": "tool_use", "id": GJ_TOOL[0], "name": GJ_TOOL[1], "input": {}}

    def td(text):
        return {"type": "thinking_delta", "thinking": text}

    def sd(sig):
        return {"type": "signature_delta", "signature": sig}

    def xd(text):
        return {"type": "text_delta", "text": text}

    def scenario(label, calls, want):
        """(problems, outs): *calls* (each enc -> bytes) after start(3) on a fresh encoder, every
        output bytes, and the joined events exactly *want*."""
        enc = encoder()
        enc.start(3)
        outs = [call(enc) for call in calls]
        bad = [i for i, out in enumerate(outs) if not isinstance(out, bytes)]
        if bad:
            return ["%s: call %d returned %s, not bytes" % (label, bad[0], type(outs[bad[0]]).__name__)], outs
        try:
            events = gj_events(b"".join(outs))
        except ValueError as exc:
            return ["%s: malformed encoder output: %s" % (label, exc)], outs
        if gj_shape(events) != gj_shape(want):
            return ["%s: events %s, expected %s" % (label, gj_shape(events), gj_shape(want))], outs
        return ["%s: event %s is %r, expected %r" % (label, gj_shape([w])[0], got[1], w[1])
                for got, w in zip(events, want) if got != w], outs

    def run_scenarios(table):
        problems, shown, outs_of = [], [], {}
        for label, calls, want in table:
            more, outs = scenario(label, calls, want)
            problems += more
            outs_of[label] = outs
            shown.append("%s: %s" % (label, "ok" if not more else "off"))
        return problems, shown, outs_of

    def j24():
        problems = gj_sink_missing(mod, "AnthropicSseEncoder")
        if problems:
            return problems, []
        fin = lambda enc: enc.finish("end_turn", dict(GJ_USAGE))   # noqa: E731 -- a call-table entry
        table = (
            ("thinking, thinking_end(''), text",
             [lambda e: e.thinking("tf j24 a"), lambda e: e.thinking(" b"), lambda e: e.thinking_end(""),
              lambda e: e.text("tf j24 t"), fin],
             [gj_block_start(0, think_start), gj_block_delta(0, td("tf j24 a")), gj_block_delta(0, td(" b")),
              gj_block_stop(0), gj_block_start(1, text_start), gj_block_delta(1, xd("tf j24 t")), gj_block_stop(1)]
             + gj_finish_events()),
            ("thinking_end(signature)",
             [lambda e: e.thinking("tf j24 x"), lambda e: e.thinking_end(GJ_SIG), lambda e: e.text("tf j24 y"), fin],
             [gj_block_start(0, think_start), gj_block_delta(0, td("tf j24 x")), gj_block_delta(0, sd(GJ_SIG)),
              gj_block_stop(0), gj_block_start(1, text_start), gj_block_delta(1, xd("tf j24 y")), gj_block_stop(1)]
             + gj_finish_events()),
            ("text closes an open thinking block",
             [lambda e: e.thinking("tf j24 x"), lambda e: e.text("tf j24 y"), fin],
             [gj_block_start(0, think_start), gj_block_delta(0, td("tf j24 x")), gj_block_stop(0),
              gj_block_start(1, text_start), gj_block_delta(1, xd("tf j24 y")), gj_block_stop(1)]
             + gj_finish_events()),
            ("thinking after text",
             [lambda e: e.text("tf j24 p"), lambda e: e.thinking("tf j24 q"), lambda e: e.thinking_end(GJ_SIG), fin],
             [gj_block_start(0, text_start), gj_block_delta(0, xd("tf j24 p")), gj_block_stop(0),
              gj_block_start(1, think_start), gj_block_delta(1, td("tf j24 q")), gj_block_delta(1, sd(GJ_SIG)),
              gj_block_stop(1)] + gj_finish_events()),
            ("tool_block closes thinking",
             [lambda e: e.thinking("tf j24 x"), lambda e: e.tool_block(*GJ_TOOL), fin],
             [gj_block_start(0, think_start), gj_block_delta(0, td("tf j24 x")), gj_block_stop(0),
              gj_block_start(1, tool_start), gj_block_delta(1, {"type": "input_json_delta", "partial_json": GJ_TOOL[2]}),
              gj_block_stop(1)] + gj_finish_events("tool_use")),
            ("finish closes thinking",
             [lambda e: e.thinking("tf j24 x"), fin],
             [gj_block_start(0, think_start), gj_block_delta(0, td("tf j24 x")), gj_block_stop(0)]
             + gj_finish_events()),
            ("thinking_end with nothing open, then text",
             [lambda e: e.thinking_end(GJ_SIG), lambda e: e.text("tf j24 z"), lambda e: e.thinking_end(GJ_SIG),
              lambda e: e.text(" more"), fin],
             [gj_block_start(0, text_start), gj_block_delta(0, xd("tf j24 z")), gj_block_delta(0, xd(" more")),
              gj_block_stop(0)] + gj_finish_events()))
        problems, shown, outs = run_scenarios(table)
        first = outs.get("thinking, thinking_end(''), text") or []
        if len(first) > 2 and isinstance(first[2], bytes):
            try:
                own = gj_events(first[2])
            except ValueError:
                own = None
            if own != [gj_block_stop(0)]:
                problems.append("thinking_end('') emitted %s, expected exactly content_block_stop[0] "
                                "(an empty signature emits no signature_delta)" % (gj_shape(own) if own else own,))
        nothing = outs.get("thinking_end with nothing open, then text") or []
        for i in (0, 2):
            if len(nothing) > i and nothing[i] != b"":
                problems.append("thinking_end with no thinking block open returned %r, expected b\"\"" % (nothing[i][:60],))
        enc = encoder()
        enc.start(1)
        enc.error("api_error", "tf j24 failure")
        for name, call in (("thinking", lambda: enc.thinking("tf")), ("thinking_end", lambda: enc.thinking_end(GJ_SIG)),
                           ("redacted_thinking", lambda: enc.redacted_thinking(GJ_SIG))):
            got = call()
            if got != b"":
                problems.append("%s() after error() returned %r, expected b\"\"" % (name, got[:60] if isinstance(got, bytes) else got))
        return problems, ["scenario    : " + s for s in shown]

    def j25():
        problems = gj_sink_missing(mod, "AnthropicSseEncoder")
        if problems:
            return problems, []
        fin = lambda enc: enc.finish("end_turn", dict(GJ_USAGE))   # noqa: E731 -- a call-table entry
        red = {"type": "redacted_thinking", "data": GJ_SIG_TWO}
        table = (
            ("text, redacted, text",
             [lambda e: e.text("tf j25 r"), lambda e: e.redacted_thinking(GJ_SIG_TWO), lambda e: e.text("tf j25 s"), fin],
             [gj_block_start(0, text_start), gj_block_delta(0, xd("tf j25 r")), gj_block_stop(0),
              gj_block_start(1, red), gj_block_stop(1),
              gj_block_start(2, text_start), gj_block_delta(2, xd("tf j25 s")), gj_block_stop(2)] + gj_finish_events()),
            ("open thinking, then redacted",
             [lambda e: e.thinking("tf j25 t"), lambda e: e.redacted_thinking(GJ_SIG_TWO), fin],
             [gj_block_start(0, think_start), gj_block_delta(0, td("tf j25 t")), gj_block_stop(0),
              gj_block_start(1, red), gj_block_stop(1)] + gj_finish_events()),
            ("redacted, then tool",
             [lambda e: e.redacted_thinking(GJ_SIG_TWO), lambda e: e.tool_block(*GJ_TOOL), fin],
             [gj_block_start(0, red), gj_block_stop(0),
              gj_block_start(1, tool_start), gj_block_delta(1, {"type": "input_json_delta", "partial_json": GJ_TOOL[2]}),
              gj_block_stop(1)] + gj_finish_events("tool_use")),
            ("two redacted in a row",
             [lambda e: e.redacted_thinking(GJ_SIG_TWO), lambda e: e.redacted_thinking(GJ_SIG), fin],
             [gj_block_start(0, red), gj_block_stop(0),
              gj_block_start(1, {"type": "redacted_thinking", "data": GJ_SIG}), gj_block_stop(1)] + gj_finish_events()))
        problems, shown, outs = run_scenarios(table)
        own = (outs.get("text, redacted, text") or [None, None])[1]
        if isinstance(own, bytes):
            try:
                own_events = gj_events(own)
            except ValueError:
                own_events = None
            if own_events != [gj_block_stop(0), gj_block_start(1, red), gj_block_stop(1)]:
                problems.append("redacted_thinking() emitted %s, expected the open block's stop, then one whole "
                                "block (start, stop; no delta)" % (gj_shape(own_events) if own_events else own_events,))
        return problems, ["scenario    : " + s for s in shown]

    def j26():
        problems = gj_sink_missing(mod, "AnthropicSseEncoder") + gj_sink_missing(mod, "_RtMessageCollector")
        if problems:
            return problems, []
        usage = dict(GJ_USAGE)
        sequence = (("start", (3,)), ("thinking", ("tf j26 a",)), ("thinking", (" b",)), ("thinking_end", (GJ_SIG,)),
                    ("text", ("tf j26 t",)), ("ping", ()), ("redacted_thinking", (GJ_SIG_TWO,)),
                    ("thinking", ("tf j26 c",)), ("tool_block", GJ_TOOL), ("thinking_end", (GJ_SIG,)),
                    ("text", ("tf j26 u",)), ("thinking_end", (GJ_SIG,)), ("finish", ("end_turn", usage)))
        failing = (("start", (3,)), ("thinking", ("tf j26 x",)), ("redacted_thinking", (GJ_SIG_TWO,)),
                   ("error", ("api_error", "tf j26 failure")))
        every = {"start", "text", "thinking", "thinking_end", "redacted_thinking", "tool_block", "finish", "error",
                 "ping"}
        used = {name for name, _args in sequence + failing}
        if used != every:
            problems.append("the call sequences use %s, expected every sink method %s" % (sorted(used), sorted(every)))
        want_content = [{"type": "thinking", "thinking": "tf j26 a b", "signature": GJ_SIG},
                        {"type": "text", "text": "tf j26 t"},
                        {"type": "redacted_thinking", "data": GJ_SIG_TWO},
                        {"type": "thinking", "thinking": "tf j26 c", "signature": ""},
                        {"type": "tool_use", "id": GJ_TOOL[0], "name": GJ_TOOL[1], "input": json.loads(GJ_TOOL[2])},
                        {"type": "text", "text": "tf j26 u"}]
        shown = []
        for label, calls in (("finished", sequence), ("failed", failing)):
            enc = encoder()
            col = mod._RtMessageCollector(GJ_MESSAGE_ID, GJ_MODEL)
            enc_out = b""
            for name, args in calls:
                enc_out += getattr(enc, name)(*args)
                got = getattr(col, name)(*args)
                if got != b"":
                    problems.append("%s: collector.%s returned %r, expected b\"\"" % (label, name, got))
            try:
                events = gj_events(enc_out)
            except ValueError as exc:
                problems.append("%s: malformed encoder output: %s" % (label, exc))
                continue
            if getattr(col, "started", None) is not True or getattr(col, "closed", None) is not True:
                problems.append("%s: collector started/closed %r/%r, expected True/True"
                                % (label, getattr(col, "started", None), getattr(col, "closed", None)))
            if label == "failed":
                if not events or events[-1][0] != "error":
                    problems.append("failed: the encoder did not end with event: error (%s)" % gj_shape(events))
                if getattr(col, "failed", None) != ("api_error", "tf j26 failure"):
                    problems.append("failed: collector.failed %r, expected ('api_error', 'tf j26 failure')"
                                    % (getattr(col, "failed", None),))
                shown.append("failed: %s" % gj_shape(events))
                continue
            folded = gj_fold(events)
            if folded["content"] != want_content:
                problems.append("finished: the folded encoder content %r, expected %r" % (folded["content"], want_content))
            if folded["stop_reason"] != "tool_use" or folded["usage"] != usage:
                problems.append("finished: folded stop_reason/usage %r/%r, expected 'tool_use'/%r"
                                % (folded["stop_reason"], folded["usage"], usage))
            message = col.message()
            if message != folded:
                problems.append("finished: collector.message() %s differs from the folded encoder %s"
                                % (json.dumps(message)[:240], json.dumps(folded)[:240]))
            shown.append("finished: %s" % gj_shape(events))
        return problems, ["sinks       : " + s for s in shown]

    def gj_step5_missing(names):
        absent = [n for n in names if not hasattr(mod, n)]
        return ["the module defines no %s (Step 5 not landed)" % ", ".join(absent)] if absent else []

    def j27():
        problems = gj_step5_missing(("_RT_RESPONSES_PROFILES",))
        if problems:
            return problems, []
        table = mod._RT_RESPONSES_PROFILES
        names = sorted(table) if isinstance(table, dict) else None
        if names != sorted(GJ_RS_PROFILES):
            problems.append("_RT_RESPONSES_PROFILES holds %r, expected exactly %s"
                            % (names, sorted(GJ_RS_PROFILES)))
        shown = []
        for name, want in GJ_RS_PROFILES.items():
            row = table.get(name) if isinstance(table, dict) else None
            if row is None:
                problems.append("%s: no row" % name)
                continue
            fields = getattr(row, "_fields", None)
            if fields != GJ_RS_FIELDS:
                problems.append("%s: the row's fields are %r, expected %r" % (name, fields, GJ_RS_FIELDS))
                continue
            bad = [field for field, got, exp in zip(GJ_RS_FIELDS, row, want)
                   if type(got) is not type(exp) or got != exp]
            for field in bad:
                problems.append("%s.%s is %r, expected %r"
                                % (name, field, getattr(row, field), want[GJ_RS_FIELDS.index(field)]))
            shown.append("%s=%s" % (name, "ok" if not bad else "%d field(s) off" % len(bad)))
        return problems, ["rows        : %s" % (", ".join(shown) or "none"),
                          "fields      : %d per row, every one asserted" % len(GJ_RS_FIELDS)]

    def j30():
        problems = gj_step5_missing(("StreamPolicy", "ADAPTERS"))
        if problems:
            return problems, []
        fields = getattr(mod.StreamPolicy, "_fields", None)
        if fields != GJ_STREAM_POLICY_FIELDS:
            problems.append("StreamPolicy._fields is %r, expected %r (L6: no second event-limit source)"
                            % (fields, GJ_STREAM_POLICY_FIELDS))
        want_policy = mod.StreamPolicy(mod._SSE_LINE_LIMIT, True)
        inbound = gf_inbound(mod, "messages", gf_body([{"role": "user", "content": "tf j30"}]),
                             gf_route(mod))
        shown = []
        for kind in GJ_BASE_HOOK_KINDS:
            adapter = mod.ADAPTERS.get(kind)
            if adapter is None:
                problems.append("%s: no ADAPTERS entry" % kind)
                continue
            missing = [h for h in ("upstream_head", "stream_policy")
                       if not callable(getattr(adapter, h, None))]
            if missing:
                problems.append("%s: no %s hook" % (kind, ", ".join(missing)))
                continue
            head = adapter.upstream_head(inbound, None)
            if head != (None, ()):
                problems.append("%s.upstream_head -> %r, expected (None, ())" % (kind, head))
            policy = adapter.stream_policy(inbound)
            if type(policy) is not mod.StreamPolicy or policy != want_policy:
                problems.append("%s.stream_policy -> %r, expected StreamPolicy(%d, True)"
                                % (kind, policy, mod._SSE_LINE_LIMIT))
            shown.append(kind)
        return problems, ["kinds       : %s -> (None, ()) and StreamPolicy(_SSE_LINE_LIMIT, True)"
                          % (", ".join(shown) or "none")]

    def j28_copy():
        """(copy module, problems): SERVER's text plus the tf-dialect row and _TfAdapter, executed
        in a fresh module namespace (not __main__: no bind, no write)."""
        with open(SERVER, "r", encoding="utf-8") as fh:
            text = fh.read()
        defs = [m.start() for m in GJ_TF_DEF_RE.finditer(text)]
        found = GJ_TF_ANCHOR_RE.search(text, defs[0]) if len(defs) == 1 else None
        nxt = GJ_TF_NEXT_DEF_RE.search(text, defs[0] + 1) if len(defs) == 1 else None
        if found is None or (nxt is not None and found.start() > nxt.start()):
            return None, ["_rt_responses_profiles: %d definition(s), and no `)` + `return {row.name: row for row "
                          "in rows}` close inside it: no place for a fourth row" % len(defs)]
        indent = found.group(1)
        patched = (text[:found.start()] + "\n" + indent * 2 + GJ_TF_ROW + text[found.start():]
                   + GJ_TF_CLASS)
        copy = types.ModuleType(GJ_TF_MODULE)
        copy.__file__ = SERVER
        sys.modules[GJ_TF_MODULE] = copy
        try:
            exec(compile(patched, SERVER + " (J28 copy)", "exec"), copy.__dict__)
        except Exception as exc:  # noqa: BLE001 -- the type is the finding: the row needs another edit
            return None, ["the copy with the fourth row does not load: %s: %s" % (type(exc).__name__, str(exc)[:200])]
        finally:
            sys.modules.pop(GJ_TF_MODULE, None)
        return copy, []

    def j28_parts(m, profile, kind, stream):
        body = {"model": GK_ROUTE, "max_tokens": 64, "stream": stream, "temperature": 0.3,
                "system": "tf j28 system",
                "tools": [{"name": "Read", "description": "tf j28: read", "input_schema": GK_SCHEMA_READ}],
                "messages": [{"role": "user", "content": "tf j28 read it"},
                             {"role": "assistant", "content": [gk_tool_use("toolu_tfj28")]},
                             {"role": "user", "content": [gk_tool_result("toolu_tfj28", "tf j28 contents")]},
                             {"role": "user", "content": "tf j28 thanks"}]}
        route = m.RouteSpec(name=GK_ROUTE, backend=GJ_TF_BACKEND, model=GK_MODEL, options={})
        backend = m.BackendSpec(name=GJ_TF_BACKEND, kind=kind, scheme="https", host="tf-dialect.invalid",
                                port=443, base_path="", allow_private=False, allow_loopback=False,
                                ca_file=None, ca_pem=None, api_key=None, auth_header="authorization",
                                forward_headers=frozenset(), connect_timeout=5.0, idle_timeout=30.0,
                                profile=profile)
        inbound = m.InboundRequest(endpoint="messages", requested_model=GK_ROUTE, body=body, stream=stream,
                                   route=route, backend=backend, client_headers={}, scrub=lambda text: text)
        return body, route, inbound

    def j28():
        problems = gj_step5_missing(("_rt_responses_profiles", "_RT_RESPONSES_PROFILES", "ResponsesAdapter",
                                     "_rt_rs_translate"))
        if problems:
            return problems, ["scope       : " + GJ_TF_SCOPE]
        copy, problems = j28_copy()
        if copy is None:
            return problems, ["scope       : " + GJ_TF_SCOPE]
        rows = copy._RT_RESPONSES_PROFILES
        want_rows = sorted(list(GJ_RS_PROFILES) + [GJ_TF_PROFILE])
        if sorted(rows) != want_rows:
            problems.append("the copy's _RT_RESPONSES_PROFILES holds %r, expected %r" % (sorted(rows), want_rows))
        if sorted(mod._RT_RESPONSES_PROFILES) != sorted(GJ_RS_PROFILES):
            problems.append("the real module's table changed: the copy was not a fresh namespace")
        cls = getattr(copy, "_TfAdapter", None)
        if cls is None or getattr(cls, "kind", None) != GJ_TF_KIND or not issubclass(cls, copy.ResponsesAdapter):
            return problems + ["the copy defines no _TfAdapter(ResponsesAdapter) of kind %r" % GJ_TF_KIND], \
                ["scope       : " + GJ_TF_SCOPE]
        if GJ_TF_PROFILE not in rows:
            return problems, ["scope       : " + GJ_TF_SCOPE]
        adapter = cls()
        body, route, inbound = j28_parts(copy, GJ_TF_PROFILE, GJ_TF_KIND, True)
        path, raw = adapter.upstream_request(inbound)
        if path != GJ_TF_PATH:
            problems.append("_TfAdapter.upstream_request -> path %r, expected the row's %r" % (path, GJ_TF_PATH))
        try:
            sent = json.loads(raw.decode("utf-8"))
        except (AttributeError, UnicodeDecodeError, ValueError):
            sent = None
        direct, _dropped = copy._rt_rs_translate(ge_clone(body), route, GJ_TF_BACKEND, rows[GJ_TF_PROFILE])
        if sent != direct:
            problems.append("_TfAdapter.upstream_request's body differs from _rt_rs_translate over the row")
        ref_body, ref_route, _ref_inbound = j28_parts(mod, GJ_TF_REFERENCE, "openai", True)
        reference, _dropped = mod._rt_rs_translate(ref_body, ref_route, GJ_TF_BACKEND,
                                                   mod._RT_RESPONSES_PROFILES[GJ_TF_REFERENCE])
        if direct != reference:
            problems.append("the tf-dialect translation differs from the real module's %s one (same dialect "
                            "fields): %s vs %s" % (GJ_TF_REFERENCE, json.dumps(direct)[:200],
                                                   json.dumps(reference)[:200]))
        if not isinstance(direct, dict) or direct.get("temperature") != 0.3:
            problems.append("the row's sampling True did not carry temperature into the body")
        _fx, raw_fx = gm_fixtures()
        _b, _r, plain = j28_parts(copy, GJ_TF_PROFILE, GJ_TF_KIND, False)
        status, message = adapter.json_response(plain, 200, raw_fx["text"])
        want_text = "".join(gm_fx_texts(_fx["text"]))
        got_text = "".join(b.get("text", "") for b in (message.get("content") or [])
                           if isinstance(b, dict) and b.get("type") == "text") if isinstance(message, dict) else None
        if status != 200 or not isinstance(message, dict) or message.get("type") != "message" or got_text != want_text:
            problems.append("_TfAdapter.json_response over tf_responses_text.sse -> %r %r, expected 200 and the "
                            "fixture's text %r" % (status, str(message)[:160], want_text))
        return problems, ["row         : %s (path %s), class _TfAdapter(ResponsesAdapter): kind = %r"
                          % (GJ_TF_PROFILE, GJ_TF_PATH, GJ_TF_KIND),
                          "translated  : a request (system, tool, call, result) == %s's; the text fixture "
                          "-> one message" % GJ_TF_REFERENCE,
                          "scope       : " + GJ_TF_SCOPE]

    def j29():
        problems = gj_step5_missing(("_RT_OAUTH_PERSIST_KEYS",))
        if problems:
            return problems, []
        keys = mod._RT_OAUTH_PERSIST_KEYS
        if not isinstance(keys, tuple) or not keys or not all(isinstance(k, str) for k in keys):
            return ["_RT_OAUTH_PERSIST_KEYS is %r, expected a non-empty tuple of str" % (keys,)], []
        if "refresh_token" not in keys:
            problems.append("_RT_OAUTH_PERSIST_KEYS holds no refresh_token: the check proves nothing "
                            "(a vacuous pass is refused)")
        bad = [k for k in keys if any(word in k for word in GJ_PERSIST_FORBIDDEN)]
        if bad:
            problems.append("_RT_OAUTH_PERSIST_KEYS persists %r: an access or ID token would reach the disk" % bad)
        return problems, ["keys        : %s" % ", ".join(keys)]

    def j31():
        # F9: Python 3.9.6 has no int_max_str_digits and int() is quadratic in a literal's
        # length, so _rt_loads must bound an integer literal itself; a ValueError is what
        # every caller's malformed-JSON path already answers (V19).  The interpreter's own
        # limit (3.11+) is lifted for the call, so the router's bound is what is measured.
        problems = gj_missing(mod, ("_rt_loads",))
        if problems:
            return problems, []
        shown = []
        saved = getattr(sys, "get_int_max_str_digits", lambda: None)()
        try:
            if saved is not None:
                sys.set_int_max_str_digits(0)
            for label, text in (("5000-digit integer", '{"n":' + "9" * 5000 + "}"),
                                ("5000-digit negative, bytes", b'{"n":-' + b"1" * 5000 + b"}")):
                try:
                    got = mod._rt_loads(text)
                except ValueError as exc:
                    shown.append("%s -> ValueError (%s)" % (label, type(exc).__name__))
                else:
                    problems.append("%s: parsed to a %s, expected ValueError" % (label, type(got.get("n")).__name__))
        finally:
            if saved is not None:
                sys.set_int_max_str_digits(saved)
        normal = '{"n":123456789012345678901234567890,"m":-7,"f":1.5}'
        try:
            got = mod._rt_loads(normal)
        except Exception as exc:  # noqa: BLE001 -- refusing a normal integer is the defect
            problems.append("a normal integer was refused: %s" % type(exc).__name__)
        else:
            if got != {"n": 123456789012345678901234567890, "m": -7, "f": 1.5}:
                problems.append("normal numbers parsed as %r" % (got,))
        return problems, ["refused     : " + s for s in shown] + ["control     : %s parsed" % normal]

    def j32():
        # F18: `content[-1]["text"] += delta` copies the whole block per delta -- quadratic on
        # the non-stream path.  The collector must gather a block's deltas and join them once;
        # the message stays byte-identical.  Functional half: many small deltas, interleaved
        # kinds, the exact joined content.  Structural half: no augmented assignment to a
        # subscript anywhere in _RtMessageCollector (the shape of the defect, no timing).
        problems = gj_sink_missing(mod, "_RtMessageCollector")
        if problems:
            return problems, []
        count = 20000
        col = mod._RtMessageCollector(GJ_MESSAGE_ID, GJ_MODEL)
        col.start(3)
        for i in range(count):
            col.thinking("t%d," % i)
        col.thinking_end(GJ_SIG)
        for i in range(count):
            col.text("x%d;" % i)
        col.ping()
        col.text("")
        col.tool_block(*GJ_TOOL)
        for i in range(3):
            col.thinking("u%d" % i)
        col.text("tail")
        col.text(" end")
        mid = col.message()
        col.text("+after")
        col.finish("end_turn", dict(GJ_USAGE))
        want = [{"type": "thinking", "thinking": "".join("t%d," % i for i in range(count)), "signature": GJ_SIG},
                {"type": "text", "text": "".join("x%d;" % i for i in range(count))},
                {"type": "tool_use", "id": GJ_TOOL[0], "name": GJ_TOOL[1], "input": json.loads(GJ_TOOL[2])},
                {"type": "thinking", "thinking": "u0u1u2", "signature": ""},
                {"type": "text", "text": "tail end+after"}]
        got = col.message()
        if got.get("content") != want:
            problems.append("content %s, expected %s" % (json.dumps(got.get("content"))[-240:], json.dumps(want)[-240:]))
        if got.get("stop_reason") != "tool_use":
            problems.append("stop_reason %r, expected tool_use" % got.get("stop_reason"))
        if (mid.get("content") or [{}])[-1] != {"type": "text", "text": "tail end+after"}:
            problems.append("message() taken mid-block then continued: the last block is %r"
                            % ((mid.get("content") or [None])[-1],))
        with open(SERVER, "r", encoding="utf-8") as fh:
            tree, findings = gj_parse(fh.read())
        problems += findings
        sites = []
        for node in ast.walk(tree) if tree is not None else ():
            if isinstance(node, ast.ClassDef) and node.name == "_RtMessageCollector":
                sites = [sub.lineno for sub in ast.walk(node)
                         if isinstance(sub, ast.AugAssign) and isinstance(sub.target, ast.Subscript)]
        if sites:
            problems.append("_RtMessageCollector grows a block with `x[k] += ...` at line(s) %s: one copy per "
                            "delta (F18), expected the deltas joined once" % sites)
        return problems, ["deltas      : %d thinking + %d text, joined content compared" % (count, count),
                          "structure   : AugAssign-on-subscript sites %s" % (sites or "none")]

    def j33():
        # F47: the rendered --help (and the login --help) teaches no form that puts the token on
        # a command line: no -H "Authorization..." argv, no `export ANTHROPIC_AUTH_TOKEN=<value>`.
        problems = gj_missing(mod, ("_rt_parser",))
        if problems:
            return problems, []
        texts = {"--help": mod._rt_parser().format_help()}
        login = getattr(mod, "_RT_LOGIN_HELP_EPILOG", None)
        if isinstance(login, str):
            texts["login epilog"] = login
        for want in (GJ_HELP_READ, GJ_HELP_CURL):
            if want not in texts["--help"]:
                problems.append("--help lacks %r" % want)
        for label, text in sorted(texts.items()):
            for bad in GJ_HELP_FORBIDDEN:
                if bad in text:
                    problems.append("%s carries %r: the token would reach the argv or the shell history" % (label, bad))
        return problems, ["checked     : %s" % ", ".join(sorted(texts)), "required    : " + GJ_HELP_READ,
                          "required    : " + GJ_HELP_CURL]

    def j34():
        # F10: json.loads silently keeps the last value of a repeated key.  _rt_loads parses
        # every inbound and upstream body, so it refuses one the way load_config does (ADR
        # 0015), as the ValueError every caller's malformed-JSON path already answers.
        problems = gj_missing(mod, ("_rt_loads",))
        if problems:
            return problems, []
        shown = []
        for label, text in GJ_DUP_REFUSED:
            try:
                got = mod._rt_loads(text)
            except ValueError:
                shown.append("%s -> ValueError" % label)
            except Exception as exc:  # noqa: BLE001 -- any other type is the finding
                problems.append("%s: raised %s, expected ValueError" % (label, type(exc).__name__))
            else:
                problems.append("%s: parsed to %r, expected ValueError (one value silently kept)" % (label, got))
        try:
            got = mod._rt_loads(GJ_DUP_CONTROL)
        except Exception as exc:  # noqa: BLE001 -- refusing distinct objects is the defect
            problems.append("control: the same key in different objects was refused: %s" % type(exc).__name__)
        else:
            if got != json.loads(GJ_DUP_CONTROL):
                problems.append("control: parsed as %r" % (got,))
        return problems, ["refused     : " + s for s in shown] + ["control     : %s parsed" % GJ_DUP_CONTROL]

    def j35():
        # F15: the role refusal's DEBUG line names the role's TYPE only (ADR 0011: a wire
        # value never reaches a log line), for a role outside the set and for a first
        # message whose role is "system"; both are still a 400 naming the field.
        problems = gj_missing(mod, ("_rt_parse_inbound", "ApiError", "log"))
        if problems:
            return problems, []
        records = []

        class Grab(logging.Handler):
            def emit(self, record):
                records.append(record.getMessage())

        grab = Grab(level=logging.DEBUG)
        logger = mod.log
        saved = logger.level
        logger.addHandler(grab)
        logger.setLevel(logging.DEBUG)
        shown = []
        try:
            for label, role, type_name in (("unknown role", GJ_ROLE_SENTINEL, "str"),
                                           ("system first", "system", "str"),
                                           ("non-string role", {GJ_ROLE_SENTINEL: 1}, "dict")):
                del records[:]
                body = {"model": GJ_MODEL, "max_tokens": 16, "messages": [{"role": role, "content": "tf j35"}]}
                try:
                    mod._rt_parse_inbound("messages", body, {}, None)
                except mod.ApiError as exc:
                    if exc.status != 400 or "messages.0.role" not in exc.message:
                        problems.append("%s: ApiError %r %r, expected 400 naming messages.0.role"
                                        % (label, exc.status, exc.message[:120]))
                except Exception as exc:  # noqa: BLE001 -- any other type is the finding
                    problems.append("%s: raised %s, expected ApiError 400" % (label, type(exc).__name__))
                else:
                    problems.append("%s: accepted, expected ApiError 400" % label)
                lines = [r for r in records if "role=" in r]
                if not lines:
                    problems.append("%s: no refusal DEBUG line naming role= was logged" % label)
                for line in lines:
                    logged = line.split("role=", 1)[1]
                    if logged != type_name:
                        problems.append("%s: the DEBUG line logs role=%s, expected the type name %r only"
                                        % (label, logged[:80], type_name))
                    if GJ_ROLE_SENTINEL in line:
                        problems.append("%s: the role value reached the log line" % label)
                shown.extend("%s -> %s" % (label, line) for line in lines)
        finally:
            logger.removeHandler(grab)
            logger.setLevel(saved)
        return problems, ["logged      : " + s for s in shown]

    def j39():
        problems = gj_missing(mod, (GJ_REG_TABLE, GJ_REG_CHECK, "ConfigError", "_rt_cfg_backend")
                              + GJ_REG_DERIVED)
        if problems:
            return problems, []
        table = getattr(mod, GJ_REG_TABLE)
        got = {
            "_KINDS": (type(mod._KINDS).__name__, mod._KINDS),
            "RESERVED_KINDS": (type(mod.RESERVED_KINDS).__name__, mod.RESERVED_KINDS),
            "_RT_KIND_AUTH_PROFILES": (type(mod._RT_KIND_AUTH_PROFILES).__name__,
                                       tuple((k, type(v).__name__, tuple(v.items()))
                                             for k, v in mod._RT_KIND_AUTH_PROFILES.items())),
            "KIND_CLASSES": (type(mod.KIND_CLASSES).__name__,
                             tuple((k, v.__name__, v is getattr(mod, v.__name__, None))
                                   for k, v in mod.KIND_CLASSES.items())),
            "ADAPTERS": (type(mod.ADAPTERS).__name__,
                         tuple((k, type(v).__name__, type(v) is mod.KIND_CLASSES.get(k))
                               for k, v in mod.ADAPTERS.items())),
        }
        want = {
            "_KINDS": ("tuple", GJ_REG_KINDS),
            "RESERVED_KINDS": ("tuple", GJ_REG_RESERVED),
            "_RT_KIND_AUTH_PROFILES": ("dict", tuple((k, "dict", v) for k, v in GJ_REG_AUTH)),
            "KIND_CLASSES": ("dict", tuple((k, n, True) for k, n in GJ_REG_CLASSES)),
            "ADAPTERS": ("dict", tuple((k, n, True) for k, n in GJ_REG_CLASSES)),
        }
        for name in GJ_REG_DERIVED:
            if got[name] != want[name]:
                problems.append("%s is %r, expected the pre-R-0084 %r" % (name, got[name], want[name]))
        table_kinds = tuple(getattr(row, "kind", None) for row in table)
        if table_kinds != GJ_REG_KINDS:
            problems.append("%s rows are %r, expected %r" % (GJ_REG_TABLE, table_kinds, GJ_REG_KINDS))
        check = getattr(mod, GJ_REG_CHECK)
        try:
            check(table)
        except Exception as exc:  # noqa: BLE001 -- a refusal of the real table is the finding
            problems.append("the real %s was refused: %s: %s" % (GJ_REG_TABLE, type(exc).__name__, exc))
        rows = {row.kind: row for row in table}
        plants = (
            ("duplicate kind", table + (rows["mistral"],)),
            ("adapter of another kind", tuple(row._replace(adapter=mod.MistralAdapter)
                                              if row.kind == "llamacpp" else row for row in table)),
            ("adapter not an Adapter", tuple(row._replace(adapter=dict) if row.kind == "llamacpp" else row
                                             for row in table)),
            ("unknown profile", tuple(row._replace(auth={"oauth": "tf-no-such-profile"})
                                      if row.kind == "codex" else row for row in table)),
            ("unknown auth mode", tuple(row._replace(auth={"tf-mode": "codex"})
                                        if row.kind == "codex" else row for row in table)),
            ("reserved kind with auth", tuple(row._replace(auth={"oauth": "codex"})
                                              if row.kind == "anthropic" else row for row in table)),
        )
        shown = []
        for label, planted in plants:
            try:
                check(planted)
            except RuntimeError as exc:
                shown.append("%s -> RuntimeError: %s" % (label, exc))
            except Exception as exc:  # noqa: BLE001 -- the wrong type is the finding
                problems.append("%s: refused with %s, expected RuntimeError" % (label, type(exc).__name__))
            else:
                problems.append("%s: %s accepted it" % (label, GJ_REG_CHECK))
        for entry, message in GJ_REG_REFUSALS:
            try:
                mod._rt_cfg_backend("tf", dict(entry), "tf-router-token-j39")
            except mod.ConfigError as exc:
                if str(exc) != message:
                    problems.append("kind %r refused as %r, expected %r" % (entry["kind"], str(exc), message))
            else:
                problems.append("kind %r was not refused" % (entry["kind"],))
        return problems, ["kinds       : %s (reserved: %s)" % (", ".join(GJ_REG_KINDS), ", ".join(GJ_REG_RESERVED))] + \
            ["refused     : " + s for s in shown]

    try:
        for cid, fn in zip(GJ_CASES, (j6, j7, j8, j12, j21, j24, j25, j26, j27, j28, j29, j30, j31, j32, j33,
                                      j34, j35, j39)):
            try:
                results[cid] = fn()
            except Exception as exc:  # noqa: BLE001 -- a broken case fails, never aborts the group
                results[cid] = (["case raised %s: %s" % (type(exc).__name__, str(exc)[:200])], [])
    except Exception as exc:  # noqa: BLE001
        setup = "the group setup raised %s: %s" % (type(exc).__name__, str(exc)[:200])
    else:
        setup = "case did not run"
    for cid in GJ_CASES:
        problems, detail = results.get(cid, ([setup], []))
        suite.record(GJ, cid, problems, detail=detail)

    group_j_hygiene(suite, fixture_root, pyc_before, tree_before)


# Step 12 (part 2): the fixture sweep J5 and its planted control J22, the
# hand-copy parity J20, the live summary-line case J14, the _log_value cut
# marker J11, and the hygiene cases J9/J10 -- which run LAST, after every live
# case of the suite has written what it writes.  Like J1-J4, the sweep is a
# function of its INPUT (the directory), never of FIXTURES itself, so J22 runs
# the SAME function, unchanged, over a planted sandbox directory.
GJ_HYGIENE_CASES = (
    "fixture sweep: no key, no TF_*",    # J5
    "control: planted key, sentinel",    # J22 (J5)
    "hand copies match _mcp_chrome",     # J20
    "one req line per request",          # J14
    "_log_value marks every cut",        # J11
    "no .pyc written in the repo",       # J9
    "no new repo path; tmp writes",      # J10
)

CHROME = H.repo_path("Scripts", "_mcp_chrome.py")
GJ_HAND_COPIES = ("_CH_TRANSLATION_PREFIXES", "_ch_embedded_ipv4", "_ch_address_refused")

# J5: the key-prefix patterns.  The suite cannot know the user's real key (plan
# "Out of Scope"), so it sweeps by SHAPE: the two prefixed key families a
# backend of this router can hold (Anthropic sk-ant-, OpenAI-style sk-) and the
# prefix-less Mistral key (32 alphanumerics with a letter and a digit, standing
# alone).  A finding names the file, the pattern and the byte offset -- never
# the matched text, which would copy a key into the report.
GJ_SWEEP_PATTERNS = (
    ("an Anthropic key prefix (sk-ant-)", re.compile(rb"sk-ant-[A-Za-z0-9_-]{8,}")),
    ("an sk- key prefix", re.compile(rb"(?<![A-Za-z0-9_-])sk-(?!ant-)[A-Za-z0-9_-]{16,}")),
    ("a Mistral-shaped key (32 alphanumerics)",
     re.compile(rb"(?<![A-Za-z0-9])(?=[A-Za-z0-9]{0,31}[0-9])(?=[A-Za-z0-9]{0,31}[A-Za-z])"
                rb"[A-Za-z0-9]{32}(?![A-Za-z0-9])")),
)
GJ_SENTINEL_HEX_RE = re.compile(r"[0-9a-f]{32}$")     # the per-run tail every TF_* sentinel ends in

# J22: the sandbox the planted control sweeps -- one clean file (must NOT be
# reported) and the two plants of the plan (both MUST be reported).
GJ_J22_CLEAN = ("tf_clean.sse",
                'data: {"id":"msg_tfll0123456789abcdef0123","type":"message_start"}\n\n')
GJ_J22_SENTINEL = "tf_planted_sentinel.json"
GJ_J22_PREFIX = "tf_planted_prefix.json"

# J14: one live router (--debug --log-file) in front of one passthrough peer.
GJ_J14_BACKEND = "tfj"
GJ_J14_ROUTE = "claude-tf-j14"
GJ_J14_MODEL = "tf-j14"
GJ_J14_TEXT = "tf j14 body " + TF_CLIENT_XKEY          # a body byte, and a sentinel, the line must never carry
GJ_J14_KEYS = ("endpoint", "route", "kind", "stream", "status", "up_status", "in", "out", "ms", "up_ms", "end")
GJ_J14_OPTIONAL = ("dropped_thinking",)                # mistral only (§9)
GJ_J14_ENDS = ("message_stop", "error", "disconnected", "shutdown", "json")
GJ_J14_LINE_S = 5.0                                    # a request's req line must be in the log within this
GJ_J14_FIELD_RE = re.compile(r"([a-z_]+)=(\S+)")
GJ_J14_COUNT = 5


def gj_sweep_needles():
    """[(label, text)]: every TF_* sentinel's value, and its stem (the value
    without its per-run hex tail), so a sentinel of an EARLIER run committed into
    a fixture is found too."""
    out = []
    for label, value in GI_SENTINEL_LABELS:
        out.append((label, value))
        stem = GJ_SENTINEL_HEX_RE.sub("", value)
        if stem and stem != value:
            out.append(("%s stem" % label, stem))
    return out


def gj_sweep(dirpath, needles=None):
    """J5: [finding] of every file under *dirpath*: a TF_* sentinel (value or
    stem) or a key-prefix pattern, by file, label and byte offset only.  A file
    that cannot be read, or is not a regular file, is a finding (the sweep
    cannot vouch for it); a directory with no file at all is a finding (a sweep
    of nothing must not pass, ADR 0017)."""
    needles = gj_sweep_needles() if needles is None else needles
    if not os.path.isdir(dirpath):
        return ["%s is not a directory" % dirpath]
    found, files = [], 0
    for root, dirs, names in os.walk(dirpath):
        dirs.sort()
        for name in sorted(names):
            path = os.path.join(root, name)
            rel = os.path.relpath(path, dirpath)
            if os.path.islink(path) or not os.path.isfile(path):
                found.append("%s: not a regular file, not swept" % rel)
                continue
            try:
                with open(path, "rb") as fh:
                    data = fh.read()
            except OSError as exc:
                found.append("%s: unreadable (%s), not swept" % (rel, type(exc).__name__))
                continue
            files += 1
            for label, value in needles:
                at = data.find(value.encode("utf-8"))
                if at >= 0:
                    found.append("%s: %s at byte %d" % (rel, label, at))
            for label, rx in GJ_SWEEP_PATTERNS:
                match = rx.search(data)
                if match:
                    found.append("%s: %s at byte %d" % (rel, label, match.start()))
    if not files:
        found.append("no file swept under %s: a sweep of nothing would pass vacuously" % dirpath)
    return found


def gj_sweep_files(dirpath):
    """The *dirpath*-relative names of every file *gj_sweep* visits under *dirpath*."""
    out = []
    for root, dirs, names in os.walk(dirpath):
        dirs.sort()
        out += [os.path.relpath(os.path.join(root, n), dirpath) for n in sorted(names)]
    return out


def gj_sweep_control(sweep, sandbox):
    """(problems, detail) of J22: *sweep* over *sandbox* holding one clean file,
    one file planted with TF_KEY_MISTRAL and one planted with a key-prefix
    string must report both plants, and nothing for the clean file.  The sweep
    is a parameter so the SC-3 red run can hand it a stub that returns no finding."""
    prefix_plant = "sk-ant-api03-tfj22" + secrets.token_hex(12)
    write_file(os.path.join(sandbox, GJ_J22_CLEAN[0]), GJ_J22_CLEAN[1])
    write_file(os.path.join(sandbox, GJ_J22_SENTINEL),
               json.dumps({"tf": "planted", "api_key": TF_KEY_MISTRAL}) + "\n")
    write_file(os.path.join(sandbox, GJ_J22_PREFIX),
               json.dumps({"tf": "planted", "note": "pasted " + prefix_plant}) + "\n")
    got = sweep(sandbox)
    problems = []
    wants = ((GJ_J22_SENTINEL, "TF_KEY_MISTRAL"), (GJ_J22_PREFIX, "Anthropic key prefix"))
    for name, needle in wants:
        if not any(f.startswith(name + ":") and needle in f for f in got):
            problems.append("the plant %s (%s) was not reported (findings: %s)"
                            % (name, needle, got[:4] or "none"))
    noise = [f for f in got if not f.startswith((GJ_J22_SENTINEL + ":", GJ_J22_PREFIX + ":"))]
    if noise:
        problems.append("the sweep reported %d finding(s) outside the two plants: %s" % (len(noise), noise[:3]))
    return problems, ["sandbox     : %s (3 files: 1 clean, 2 planted)"
                      % os.path.relpath(sandbox, H.REPO_ROOT)] + \
        ["planted     : %s" % f for f in (got or ["no finding"])]


def gj_top_level(tree, name):
    """The module-level nodes of *tree* that define *name* (def, class, or assignment)."""
    hits = []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and node.name == name:
            hits.append(node)
        elif isinstance(node, ast.Assign) and any(gj_is_name(t, name) for t in node.targets):
            hits.append(node)
        elif isinstance(node, ast.AnnAssign) and gj_is_name(node.target, name):
            hits.append(node)
    return hits


def rule_j20(copy_source, origin_source, names=GJ_HAND_COPIES):
    """J20: for each of *names*, the one module-level node in *copy_source* has the
    same ast.dump as the one in *origin_source* (docstrings included, comments and
    line numbers not).  A finding names the drifted copy."""
    copy_tree, found = gj_parse(copy_source)
    origin_tree, more = gj_parse(origin_source)
    found += ["origin: %s" % f for f in more]
    if copy_tree is None or origin_tree is None:
        return found
    for name in names:
        copies, origins = gj_top_level(copy_tree, name), gj_top_level(origin_tree, name)
        if len(copies) != 1 or len(origins) != 1:
            found.append("%s: defined %d time(s) in the copy and %d time(s) in the source, expected once each"
                         % (name, len(copies), len(origins)))
            continue
        got, want = ast.dump(copies[0]), ast.dump(origins[0])
        if got != want:
            at = next((i for i, (a, b) in enumerate(zip(got, want)) if a != b), min(len(got), len(want)))
            found.append("%s: the copy (line %d) has drifted from its source (line %d): ast.dump differs "
                         "at offset %d (copy %r, source %r)"
                         % (name, copies[0].lineno, origins[0].lineno, at,
                            got[max(0, at - 20):at + 40], want[max(0, at - 20):at + 40]))
    return found


def gj_req_lines(path):
    """The messages of every `req ` line of the router log at *path*."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            text = fh.read()
    except OSError:
        return []
    out = []
    for line in text.splitlines():
        _head, sep, msg = line.partition(" llm-router DEBUG ")
        if sep and msg.startswith("req "):
            out.append(msg)
    return out


def gj_j14_script(_index, request):
    """The J14 peer: count_tokens answers a count, a streamed request a stream, else JSON."""
    if "count_tokens" in (request.get("line") or ""):
        return [("respond_json", 200, {"input_tokens": 5})]
    try:
        stream = json.loads((request.get("body") or b"").decode("utf-8")).get("stream")
    except (UnicodeDecodeError, ValueError, AttributeError):
        stream = None
    if stream:
        return [("respond_sse", GD_STREAM_LINES)]
    return [("respond_json", 200, GD_ANSWER)]


def gj_j14(fixture_root):
    """(problems, detail) of J14: five POSTs, one at a time, each waited for in the
    log before the next: exactly one `req ` line each, the §9 key set, the
    client's status, and no sentinel and no body byte on any line."""
    sandbox = new_sandbox(fixture_root, "j14")
    logpath = os.path.join(sandbox, "j14.log")
    peer = ScriptedPeer(script=gj_j14_script)
    proc = None
    problems, detail = [], []
    try:
        cfg = {"auth_token": TF_ROUTER_TOKEN,
               "backends": {GJ_J14_BACKEND: {"kind": "passthrough", "base_url": peer.url(),
                                             "api_key": TF_KEY_PASS, "auth_header": "x-api-key"}},
               "routes": {GJ_J14_ROUTE: {"backend": GJ_J14_BACKEND, "model": GJ_J14_MODEL}}}
        cfgpath = write_config(sandbox, cfg)
        proc = RouterProc(sandbox, cfgpath, label="j14", extra_argv=("--debug", "--log-file", logpath))
        if proc.wait_ready() is None:
            return [gb_not_ready(proc)], []
        client = proc.client()
        body = {"model": GJ_J14_ROUTE, "max_tokens": 16, "stream": False,
                "messages": [{"role": "user", "content": GJ_J14_TEXT}]}
        sbody = dict(body, stream=True)
        xkey = {"x-api-key": TF_CLIENT_XKEY}
        size = len(json.dumps(body).encode("utf-8"))
        ssize = len(json.dumps(sbody).encode("utf-8"))
        # (label, send, want): send() -> the status the client saw; want: the fields the line must hold.
        wrong = RouterClient(proc.port, "tf-wrong-token-" + secrets.token_hex(16))

        def post_json(c, path, obj):
            return lambda: c.post(path=path, obj=obj, headers=xkey)[0]

        def post_stream():
            conn, resp, why = open_stream(client, sbody, headers=xkey)
            if conn is None:
                problems.extend("stream: %s" % w for w in why)
                return None
            try:
                read_stream(resp)
            finally:
                close_stream(conn, resp)
            return 200

        plan = (
            ("json", post_json(client, None, body),
             {"endpoint": "'messages'", "route": repr(GJ_J14_ROUTE), "kind": "'passthrough'",
              "stream": "0", "up_status": "200", "in": str(size), "end": "'json'"}),
            ("stream", post_stream,
             {"endpoint": "'messages'", "route": repr(GJ_J14_ROUTE), "stream": "1",
              "up_status": "200", "in": str(ssize), "end": "'message_stop'"}),
            ("count_tokens", post_json(client, "/v1/messages/count_tokens", body),
             {"endpoint": "'count_tokens'", "route": repr(GJ_J14_ROUTE), "in": str(size), "end": "'json'"}),
            ("bad bearer", post_json(wrong, None, body),
             {"endpoint": "'-'", "up_status": "0", "in": "0", "up_ms": "0", "end": "'json'"}),
            ("unknown path", post_json(client, "/v1/tf-j14-nope", body),
             {"endpoint": "'-'", "up_status": "0", "in": "0", "up_ms": "0", "end": "'json'"}),
        )
        assert len(plan) == GJ_J14_COUNT
        statuses = []
        for i, (label, send, want) in enumerate(plan):
            status = send()
            statuses.append(status)
            deadline = time.monotonic() + GJ_J14_LINE_S
            while len(gj_req_lines(logpath)) <= i and time.monotonic() < deadline:
                time.sleep(0.05)
            lines = gj_req_lines(logpath)
            if len(lines) != i + 1:
                problems.append("%s: %d req line(s) after request %d, expected %d"
                                % (label, len(lines), i + 1, i + 1))
                continue
            fields = GJ_J14_FIELD_RE.findall(lines[i][len("req "):])
            keys = [k for k, _v in fields]
            values = dict(fields)
            if [k for k in keys if k not in GJ_J14_OPTIONAL] != list(GJ_J14_KEYS) \
                    or len(keys) != len(set(keys)):
                problems.append("%s: key set %s, expected %s (+ optional %s)"
                                % (label, keys, list(GJ_J14_KEYS), list(GJ_J14_OPTIONAL)))
            if values.get("end", "").strip("'") not in GJ_J14_ENDS:
                problems.append("%s: end=%s is not one of %s" % (label, values.get("end"), GJ_J14_ENDS))
            if status is not None and values.get("status") != str(status):
                problems.append("%s: status=%s, the client saw %s" % (label, values.get("status"), status))
            for key, value in want.items():
                if values.get(key) != value:
                    problems.append("%s: %s=%s, expected %s" % (label, key, values.get(key), value))
            for key in ("ms", "up_ms", "out"):
                if not (values.get(key) or "").isdigit():
                    problems.append("%s: %s=%s is not a non-negative integer" % (label, key, values.get(key)))
        code = proc.close()
        lines = gj_req_lines(logpath)
        if len(lines) != GJ_J14_COUNT:
            problems.append("%d req line(s) for %d requests after shutdown (exit %r)"
                            % (len(lines), GJ_J14_COUNT, code))
        for label, needle in gj_sweep_needles() + [("a body byte", "tf j14 body")]:
            hit = [i for i, line in enumerate(lines) if needle in line]
            if hit:
                problems.append("req line(s) %s carry %s" % (hit, label))
        detail = ["requests    : %s -> status %s" % (", ".join(p[0] for p in plan), statuses),
                  "log         : %d req line(s); keys of the first: %s"
                  % (len(lines), " ".join(k for k, _v in GJ_J14_FIELD_RE.findall(lines[0][4:]))
                     if lines else "-")]
        detail += ["line        : %s" % line[:160] for line in lines]
    finally:
        if proc is not None:
            proc.close()
        peer.close()
    return problems, detail


def group_j_hygiene(suite, fixture_root, pyc_before, tree_before):
    """J5, J22, J20, J14, J11, then J9/J10 (last: every live case has written by now)."""
    results = {}

    def guarded(cid, fn):
        try:
            results[cid] = fn()
        except Exception as exc:  # noqa: BLE001 -- a broken case fails, never aborts the group
            results[cid] = (["case raised %s: %s" % (type(exc).__name__, str(exc)[:200])], [])

    j5, j22, j20, j14, j11, j9, j10 = GJ_HYGIENE_CASES

    def case_j5():
        files = gj_sweep_files(FIXTURES)
        return gj_sweep(FIXTURES), ["swept       : %d file(s) under %s"
                                    % (len(files), os.path.relpath(FIXTURES, H.REPO_ROOT)),
                                    "needles     : %d TF_* value/stem form(s), %d key pattern(s)"
                                    % (len(gj_sweep_needles()), len(GJ_SWEEP_PATTERNS))]

    def case_j20():
        with open(SERVER, "r", encoding="utf-8") as fh:
            copy_source = fh.read()
        with open(CHROME, "r", encoding="utf-8") as fh:
            origin_source = fh.read()
        return rule_j20(copy_source, origin_source), \
            ["copies      : %s" % ", ".join(GJ_HAND_COPIES),
             "compared    : ast.dump of %s vs %s (docstrings in, comments and line numbers out)"
             % (os.path.relpath(SERVER, H.REPO_ROOT), os.path.relpath(CHROME, H.REPO_ROOT))]

    def case_j11():
        # Copied from tests/test_mcp_proxy.py L4 with SERVER = the router: an
        # uncut value of non-printables whose repr() overruns the 4 x width cap
        # ends in "...", and a short printable str is its repr() exactly.
        problems = []
        mod = H.load_module_from_path("ph_llm_router_j11", SERVER)
        width = mod._LOG_VALUE_WIDTH
        wide = mod._log_value("\U0010ffff" * width)
        if not wide.endswith("..."):
            problems.append("%d x U+10FFFF: no '...' marker on a capped repr (%d chars)" % (width, len(wide)))
        if len(wide) > 4 * width + 3:
            problems.append("%d x U+10FFFF: %d chars, cap %d" % (width, len(wide), 4 * width + 3))
        short = mod._log_value("messages")
        if short != repr("messages"):
            problems.append("short str logged as %r, expected %r" % (short, repr("messages")))
        return problems, ["capped      : %d x U+10FFFF -> %d chars, ends %r" % (width, len(wide), wide[-3:]),
                          "short       : %s" % short]

    guarded(j5, case_j5)
    guarded(j22, lambda: gj_sweep_control(gj_sweep, new_sandbox(fixture_root, "j22")))
    guarded(j20, case_j20)
    guarded(j14, lambda: gj_j14(fixture_root))
    guarded(j11, case_j11)

    # J9 / J10 -- copied from tests/test_mcp_proxy.py group_l (L1-L3).
    def case_j9():
        pyc_after = H.pycache_snapshot()
        new = sorted(set(pyc_after) - set(pyc_before))
        touched = sorted(k for k in set(pyc_after) & set(pyc_before) if pyc_after[k] != pyc_before[k])
        return ([] if not (new or touched) else ["new=%r touched=%r" % (new, touched)],
                ["pyc before=%d after=%d" % (len(pyc_before), len(pyc_after)),
                 "note        : the router runs with -B and the suite sets dont_write_bytecode"])

    def case_j10():
        problems = []
        stray = [p for p in WRITES
                 if not os.path.abspath(p).startswith(os.path.abspath(FIXTURE_BASE) + os.sep)]
        if stray:
            problems.append("%d write(s) outside the sandbox: %s" % (len(stray), ", ".join(stray)))
        added = sorted(H.repo_tree() - tree_before)
        if added:
            problems.append("%d new path(s): %s" % (len(added), added[:5]))
        return problems, ["sandbox     : %s/run-<unique>" % os.path.relpath(FIXTURE_BASE, H.REPO_ROOT),
                          "writes      : %d" % len(WRITES),
                          "note        : the scratch area is excluded by _harness.repo_tree, so the "
                          "fixtures are invisible here by construction, not by luck"]

    guarded(j9, case_j9)
    guarded(j10, case_j10)
    for cid in GJ_HYGIENE_CASES:
        problems, detail = results.get(cid, (["case did not run"], []))
        suite.record(GJ, cid, problems, detail=detail)


# ---------------------------------------------------------------------------

# The groups in run order.  A group whose step has not landed yet is absent
# from this module and is simply not called.  K-O run before I and J: I1 sweeps
# every stderr and log file the run collected, and J9/J10 compare the bytecode
# and repo snapshots taken at the start, so both must run last.
GROUP_ORDER = ("group_a", "group_b", "group_c", "group_d", "group_e",
               "group_f", "group_g", "group_h", "group_k", "group_l",
               "group_m", "group_n", "group_o", "group_i", "group_j")


def run(opts=None):
    opts = opts or H.Options()
    suite = H.Suite(NAME,
                    title="llm-router routes by model and translates at the edge: "
                          "config, front, outbound, five backend kinds, "
                          "timeouts and secret hygiene against scripted peers",
                    opts=opts, mode="grouped", cid_width=30)
    pyc_before = H.pycache_snapshot()
    tree_before = H.repo_tree()
    del WRITES[:]
    del LOG_PATHS[:]
    del RESPONSE_BODIES[:]

    os.makedirs(FIXTURE_BASE, exist_ok=True)
    fixture_root = tempfile.mkdtemp(prefix="run-", dir=FIXTURE_BASE)
    WRITES.append(fixture_root)
    try:
        for name in GROUP_ORDER:
            group = globals().get(name)
            if group is None:
                continue
            if name == "group_j":
                group(suite, fixture_root, pyc_before, tree_before)
            else:
                group(suite, fixture_root)
    finally:
        if opts.keep:
            print("\n[--keep] fixtures retained at: %s" % fixture_root)
        else:
            shutil.rmtree(fixture_root, ignore_errors=True)

    suite.print_summary()
    return suite


def main(argv=None):
    opts = H.parse_options(argv)
    if opts.help:
        print(__doc__)
        return 0
    return run(opts).exit_code


if __name__ == "__main__":
    sys.exit(main())
